/** Search-first TV client. All displayed video records come from the selected API response. */
public class MainActivity extends Activity {
    static final int INK=0xff24343d,MUTED=0xff6e7880,BG=0xfff6f5f2,ACCENT=0xffce5467,LINE=0xffe4e5e5;
    private final Handler main=new Handler(Looper.getMainLooper());
    private final ThreadPoolExecutor worker=new ThreadPoolExecutor(2,2,20,TimeUnit.SECONDS,new ArrayBlockingQueue<>(8),new ThreadPoolExecutor.AbortPolicy());
    private SessionStore session;private VideoApi videos;private AccountApi accounts;private ThumbnailLoader thumbnails;
    private AccountApi.Profile profile;private AccountApi.Folder selectedFolder;
    private LinearLayout root,content,tabs;private TextView heading;private Button accountButton;private EditText searchInput;
    private ScrollView scroll;private Dialog modal;private Future<?> pending;private Runnable qrPoll,readRetry,interruptedRead;private int generation;
    private String page="search",query="";private int currentPage=1;private long historyMax,historyViewAt;
    private boolean active,destroyed,loading,qrOpen,resumeRead;private final List<VideoApi.Video> records=new ArrayList<>();
    protected BiliHttp createHttp(SessionStore value){return new BiliHttp(value);}
    protected VideoApi createVideoApi(BiliHttp value){return new VideoApi(value);}
    protected AccountApi createAccountApi(BiliHttp value,SessionStore store){return new AccountApi(value,store);}
    protected ThumbnailLoader createThumbnailLoader(){return new ThumbnailLoader();}
    String tr(String zh,String en){return getResources().getConfiguration().locale.getLanguage().equals("zh")?zh:en;}
    private int dp(float value){return Math.round(value*getResources().getDisplayMetrics().density);}
    @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().setFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN,WindowManager.LayoutParams.FLAG_FULLSCREEN);
        session=new SessionStore(this);BiliHttp http=createHttp(session);videos=createVideoApi(http);accounts=createAccountApi(http,session);thumbnails=createThumbnailLoader();
        createShell();showWelcome();
    }
    private void createShell(){
        boolean compact=getResources().getConfiguration().screenHeightDp<430;
        root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(BG);root.setPadding(dp(compact?18:26),dp(compact?10:18),dp(compact?18:26),dp(compact?8:12));setContentView(root);
        LinearLayout top=row();TextView brand=text("BiliTV",compact?22:26,INK);brand.setTypeface(null,1);top.addView(brand,new LinearLayout.LayoutParams(0,dp(compact?36:46),1));
        accountButton=button(tr("扫码登录","Sign in"),v->accountAction());accountButton.setTag("account");top.addView(accountButton);root.addView(top);
        tabs=row();tabs.setPadding(0,dp(compact?4:8),0,dp(compact?8:12));for(String id:new String[]{"search","favorites","history"}){Button b=button(tabTitle(id),v->navigate(id));b.setTag("tab-"+id);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(compact?34:42),1);lp.rightMargin=dp(8);tabs.addView(b,lp);}root.addView(tabs);
        LinearLayout search=row();searchInput=new EditText(this);searchInput.setSingleLine(true);searchInput.setTextSize(16);searchInput.setTextColor(INK);searchInput.setHintTextColor(MUTED);searchInput.setHint(tr("搜索视频、作者或 BV 号","Search videos, creators or BV number"));searchInput.setPadding(dp(14),0,dp(14),0);searchInput.setBackground(fieldBackground());searchInput.setImeOptions(EditorInfo.IME_ACTION_SEARCH);searchInput.setInputType(android.text.InputType.TYPE_CLASS_TEXT);searchInput.setTag("search-input");
        searchInput.setOnEditorActionListener((v,action,event)->{if(action==EditorInfo.IME_ACTION_SEARCH||event!=null&&event.getKeyCode()==KeyEvent.KEYCODE_ENTER&&event.getAction()==KeyEvent.ACTION_UP){search();return true;}return false;});
        search.addView(searchInput,new LinearLayout.LayoutParams(0,dp(compact?40:46),1));Button submit=button(tr("搜索","Search"),v->search());submit.setTag("search-submit");LinearLayout.LayoutParams submitLp=new LinearLayout.LayoutParams(dp(96),dp(compact?40:46));submitLp.leftMargin=dp(10);search.addView(submit,submitLp);root.addView(search);
        heading=text(tr("想看什么，直接搜索","Find what you want to watch"),compact?16:18,INK);heading.setTypeface(null,1);heading.setPadding(0,dp(compact?10:20),0,dp(compact?8:12));root.addView(heading);
        scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setClipToPadding(false);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);scroll.addView(content,new ScrollView.LayoutParams(-1,-2));root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
        TextView foot=text(tr("方向键移动 · 确定选择 · 返回上一级","Arrows to move · OK to select · Back to return"),10,MUTED);foot.setPadding(0,dp(compact?5:9),0,0);root.addView(foot);updateTabs();searchInput.requestFocus();
    }
    private String tabTitle(String id){return "favorites".equals(id)?tr("我的收藏","Favorites"):"history".equals(id)?tr("观看历史","History"):tr("搜索","Search");}
    private LinearLayout row(){LinearLayout value=new LinearLayout(this);value.setOrientation(LinearLayout.HORIZONTAL);value.setGravity(Gravity.CENTER_VERTICAL);return value;}
    private TextView text(String label,int size,int color){TextView v=new TextView(this);v.setText(label);v.setTextSize(size);v.setTextColor(color);v.setGravity(Gravity.CENTER_VERTICAL);return v;}
    private GradientDrawable shape(int fill,int border){GradientDrawable d=new GradientDrawable();d.setColor(fill);d.setCornerRadius(dp(9));d.setStroke(dp(1),border);return d;}
    private StateListDrawable fieldBackground(){StateListDrawable d=new StateListDrawable();d.addState(new int[]{android.R.attr.state_focused},shape(0xffffffff,ACCENT));d.addState(new int[]{},shape(0xffffffff,LINE));return d;}
    private Button button(String label,View.OnClickListener action){Button b=new Button(this);b.setText(label);b.setTextSize(13);b.setTextColor(INK);b.setAllCaps(false);b.setMinHeight(0);b.setMinimumHeight(0);b.setMinWidth(0);b.setMinimumWidth(0);b.setPadding(dp(14),dp(6),dp(14),dp(6));b.setBackground(fieldBackground());b.setOnClickListener(action);return b;}
    private void updateTabs(){for(int i=0;i<tabs.getChildCount();i++){View b=tabs.getChildAt(i);boolean selected=("tab-"+page).equals(b.getTag());b.setSelected(selected);((Button)b).setTextColor(selected?ACCENT:INK);StateListDrawable bg=fieldBackground();if(selected){bg=new StateListDrawable();bg.addState(new int[]{android.R.attr.state_focused},shape(0xfffce4e8,ACCENT));bg.addState(new int[]{},shape(0xfffcecef,0xffecc7ce));}b.setBackground(bg);}}
    private void accountLabel(){accountButton.setText(profile==null?tr("扫码登录","Sign in"):profile.name);}
    private void clearContent(){content.removeAllViews();scroll.scrollTo(0,0);loading=false;}
    private void showWelcome(){clearContent();records.clear();heading.setText(tr("想看什么，直接搜索","Find what you want to watch"));empty(tr("只保留你想看的内容","Just the videos you choose"),tr("输入关键词或 BV 号开始。登录后，可以打开收藏夹和观看历史。","Enter keywords or a BV number. Sign in to open your favorites and watch history."),null,null);}
    private void empty(String title,String subtitle,String label,Runnable action){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setGravity(Gravity.CENTER);box.setPadding(dp(20),dp(26),dp(20),dp(26));box.setBackground(shape(0xffffffff,LINE));TextView t=text(title,21,INK);t.setGravity(Gravity.CENTER);box.addView(t);TextView sub=text(subtitle,13,MUTED);sub.setGravity(Gravity.CENTER);sub.setPadding(0,dp(14),0,dp(20));box.addView(sub);if(action!=null)box.addView(button(label,v->action.run()));content.addView(box,new LinearLayout.LayoutParams(-1,-2));}
    private void showLoading(){clearContent();loading=true;ProgressBar p=new ProgressBar(this);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(dp(38),dp(38));lp.gravity=Gravity.CENTER_HORIZONTAL;lp.topMargin=dp(32);content.addView(p,lp);TextView t=text(tr("正在读取…","Loading…"),14,MUTED);t.setGravity(Gravity.CENTER);content.addView(t);}
    private void showError(Throwable error,Runnable retry){if(error instanceof BiliHttp.ApiException&&((BiliHttp.ApiException)error).kind==BiliHttp.Kind.AUTH_REQUIRED){session.clear();profile=null;accountLabel();showSignIn();return;}clearContent();empty(tr("暂时无法读取","Unable to load"),errorText(error),tr("重试","Retry"),retry);}
    private String errorText(Throwable error){if(error instanceof BiliHttp.ApiException){switch(((BiliHttp.ApiException)error).kind){case AUTH_REQUIRED:return tr("登录已失效，请重新扫码登录。","Your session has expired. Please sign in again.");case RATE_LIMITED:return tr("服务暂时限制了请求，请稍后重试。","The service has limited requests. Please try again later.");case NOT_FOUND:return tr("这个视频已不可用。","This video is no longer available.");case RESTRICTED:return tr("当前账号或地区暂时无法访问此内容。","This content is unavailable for your account or region.");default:break;}}return tr("请检查网络，然后重试。","Check your network connection and try again.");}
    private interface Work<T>{T run()throws Exception;}private interface Done<T>{void run(T value);}
    private <T> void request(Work<T> work,Done<T> success,Done<Exception> failure){
        cancelPending();final int ticket=generation;try{pending=worker.submit(()->{try{T value=work.run();main.post(()->{if(valid(ticket)){pending=null;loading=false;success.run(value);}});}catch(Exception e){main.post(()->{if(valid(ticket)){pending=null;loading=false;failure.run(e);}});}});}catch(RejectedExecutionException e){loading=false;failure.run(e);}
    }
    private boolean valid(int ticket){return !destroyed&&active&&ticket==generation;}
    private void cancelPending(){generation++;if(pending!=null)pending.cancel(true);pending=null;worker.purge();}
    private void search(){String value=searchInput.getText().toString().trim();if(value.isEmpty()){searchInput.setError(tr("请输入关键词","Enter a search term"));searchInput.requestFocus();return;}if(value.length()>100){searchInput.setError(tr("关键词最多 100 个字符","Use at most 100 characters"));return;}
        ((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(searchInput.getWindowToken(),0);page="search";query=value;currentPage=1;updateTabs();fetchSearch();}
    private void navigate(String destination){dismissModal(false);interruptedRead=null;cancelPending();page=destination;selectedFolder=null;currentPage=1;historyMax=historyViewAt=0;updateTabs();if("search".equals(page)){if(query.isEmpty())showWelcome();else fetchSearch();}else requireAccount(()->{if("favorites".equals(page))fetchFolders();else fetchHistory(false);});}
    private void fetchSearch(){heading.setText(tr("搜索结果 · ","Results · ")+query);readRetry=this::fetchSearch;showLoading();request(()->videos.search(query,currentPage),result->showVideos(result.items,currentPage>1,result.hasMore,()->{currentPage--;fetchSearch();},()->{currentPage++;fetchSearch();}),e->showError(e,this::fetchSearch));}
    private void requireAccount(Runnable after){if(profile!=null){after.run();return;}if(!session.hasSession()){showSignIn();return;}readRetry=()->requireAccount(after);showLoading();request(accounts::profile,value->{profile=value;accountLabel();after.run();},e->{profile=null;accountLabel();if(e instanceof BiliHttp.ApiException&&((BiliHttp.ApiException)e).kind==BiliHttp.Kind.AUTH_REQUIRED)showSignIn();else showError(e,()->requireAccount(after));});}
    private void showSignIn(){clearContent();heading.setText(tabTitle(page));empty(tr("登录后继续","Sign in to continue"),tr("用哔哩哔哩手机端扫码，读取你的收藏和历史。","Scan with the Bilibili mobile app to access your favorites and history."),tr("扫码登录","Sign in"),this::login);}
    private void fetchFolders(){selectedFolder=null;heading.setText(tr("我的收藏夹","My folders"));readRetry=this::fetchFolders;showLoading();request(()->accounts.folders(profile.mid),folders->{clearContent();if(folders.isEmpty()){empty(tr("还没有收藏夹","No folders yet"),tr("在哔哩哔哩账号中创建收藏夹后重试。","Create a folder on your Bilibili account, then try again."),tr("刷新","Refresh"),this::fetchFolders);return;}for(AccountApi.Folder folder:folders){Button b=button(folder.title+"  ·  "+folder.count,v->{selectedFolder=folder;currentPage=1;fetchFavorites();});LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(52));lp.bottomMargin=dp(9);content.addView(b,lp);}},e->showError(e,this::fetchFolders));}
    private void fetchFavorites(){heading.setText(selectedFolder.title);readRetry=this::fetchFavorites;showLoading();request(()->accounts.favorites(selectedFolder.id,currentPage),result->{showVideos(result.items,currentPage>1,result.hasMore,()->{currentPage--;fetchFavorites();},()->{currentPage++;fetchFavorites();});content.addView(button(tr("返回收藏夹","Back to folders"),v->fetchFolders()),0);},e->showError(e,this::fetchFavorites));}
    private void fetchHistory(boolean append){heading.setText(tr("观看历史","Watch history"));readRetry=()->fetchHistory(append);showLoading();request(()->accounts.history(historyMax,historyViewAt),result->{if(!append)records.clear();records.addAll(result.videos);historyMax=result.nextMax;historyViewAt=result.nextViewAt;showVideos(new ArrayList<>(records),false,result.hasMore,null,()->fetchHistory(true));},e->showError(e,()->fetchHistory(append)));}
    private void showVideos(List<VideoApi.Video> items,boolean previous,boolean next,Runnable prevAction,Runnable nextAction){clearContent();if(items.isEmpty()){empty(tr("没有找到视频","No videos found"),tr("换个关键词，或者稍后刷新。","Try another keyword or refresh later."),null,null);}
        int columns=getResources().getConfiguration().screenWidthDp<760?3:4;for(int start=0;start<items.size();start+=columns){LinearLayout row=row();row.setGravity(Gravity.TOP);for(int j=0;j<columns;j++){LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);if(j<columns-1)lp.rightMargin=dp(12);if(start+j<items.size())row.addView(videoCard(items.get(start+j),start+j),lp);else row.addView(new View(this),lp);}LinearLayout.LayoutParams rowLp=new LinearLayout.LayoutParams(-1,-2);rowLp.bottomMargin=dp(14);content.addView(row,rowLp);}
        if(previous||next){LinearLayout pager=row();pager.setGravity(Gravity.CENTER);if(previous)pager.addView(button(tr("上一页","Previous"),v->prevAction.run()));if(next){Button b=button("history".equals(page)?tr("加载更多","Load more"):tr("下一页","Next"),v->nextAction.run());LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-2,dp(42));lp.leftMargin=dp(12);pager.addView(b,lp);}content.addView(pager);}
    }
    private View videoCard(VideoApi.Video video,int index){LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(dp(7),dp(7),dp(7),dp(9));card.setBackground(fieldBackground());card.setFocusable(true);card.setClickable(true);card.setTag("video-"+index);card.setContentDescription(video.title+" · "+video.author);card.setOnClickListener(v->detail(video));
        FrameLayout imageBox=new FrameLayout(this);ImageView image=new ImageView(this);image.setScaleType(ImageView.ScaleType.CENTER_CROP);image.setBackgroundColor(new int[]{0xffeaded8,0xffdae6e7,0xffe0ddec,0xffe6e4d7}[index%4]);imageBox.addView(image,new FrameLayout.LayoutParams(-1,-1));TextView play=text("▶",24,0xff78868a);play.setGravity(Gravity.CENTER);imageBox.addView(play,new FrameLayout.LayoutParams(-1,-1));if(video.cover!=null&&!video.cover.isEmpty()){imageBox.removeView(play);thumbnails.load(video.cover,image);}int height=getResources().getConfiguration().screenWidthDp<760?78:100;card.addView(imageBox,new LinearLayout.LayoutParams(-1,dp(height)));
        TextView title=text(video.title,13,INK);title.setMaxLines(2);title.setMinLines(2);title.setEllipsize(TextUtils.TruncateAt.END);title.setPadding(dp(3),dp(8),dp(3),0);card.addView(title);TextView meta=text(video.author+" · "+duration(video.durationSeconds),10,MUTED);meta.setSingleLine(true);meta.setEllipsize(TextUtils.TruncateAt.END);meta.setPadding(dp(3),dp(4),dp(3),0);card.addView(meta);return card;}
    static String duration(long seconds){return String.format(Locale.ROOT,"%d:%02d",Math.max(0,seconds)/60,Math.max(0,seconds)%60);}
    private LinearLayout dialogBody(String title){if(modal==null&&loading&&readRetry!=null)interruptedRead=readRetry;dismissModal(false);modal=new Dialog(this);modal.requestWindowFeature(Window.FEATURE_NO_TITLE);LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(22),dp(18),dp(22),dp(18));box.setBackground(shape(0xffffffff,LINE));TextView h=text(title,20,INK);h.setTypeface(null,1);h.setPadding(0,0,0,dp(12));box.addView(h);ScrollView dialogScroll=new ScrollView(this);dialogScroll.addView(box);modal.setContentView(dialogScroll);modal.setOnCancelListener(d->closeModal());modal.show();Window w=modal.getWindow();if(w!=null){w.setBackgroundDrawableResource(android.R.color.transparent);w.setLayout(Math.min(getResources().getDisplayMetrics().widthPixels-dp(50),dp(620)),Math.min(getResources().getDisplayMetrics().heightPixels-dp(40),dp(480)));}return box;}
    private void closeModal(){dismissModal(true);}
    private void dismissModal(boolean restoreRead){cancelPending();main.removeCallbacksAndMessages("qr");if(qrPoll!=null)main.removeCallbacks(qrPoll);qrPoll=null;if(qrOpen){qrOpen=false;session.clear();}Dialog old=modal;modal=null;if(old!=null)old.dismiss();if(restoreRead&&interruptedRead!=null){Runnable resume=interruptedRead;interruptedRead=null;if(active&&!destroyed)resume.run();else if(!destroyed){readRetry=resume;resumeRead=true;}}}
    private void detail(VideoApi.Video selected){LinearLayout box=dialogBody(tr("视频详情","Video details"));TextView status=text(tr("正在读取…","Loading…"),14,MUTED);box.addView(status);request(()->videos.detail(selected.bvid),value->{if(modal==null)return;box.removeView(status);TextView title=text(value.video.title,17,INK);title.setMaxLines(3);box.addView(title);TextView by=text(value.video.author+" · "+duration(value.video.durationSeconds),12,MUTED);by.setPadding(0,dp(8),0,dp(10));box.addView(by);TextView description=text(value.description,12,MUTED);description.setMaxLines(3);description.setEllipsize(TextUtils.TruncateAt.END);box.addView(description);
            ScrollView partScroll=new ScrollView(this);LinearLayout parts=new LinearLayout(this);parts.setOrientation(LinearLayout.VERTICAL);partScroll.addView(parts);int selectedIndex=0;for(int i=0;i<value.parts.size();i++)if(value.parts.get(i).cid==selected.cid)selectedIndex=i;final int startIndex=selectedIndex;
            Button play=button(selected.positionSeconds>0?tr("继续播放","Continue watching"):tr("播放","Play"),v->{if(!value.parts.isEmpty()){VideoApi.Part part=value.parts.get(startIndex);openPlayer(value.video,part.cid,selected.cid==part.cid?selected.positionSeconds:0);}});play.setEnabled(!value.parts.isEmpty());LinearLayout actions=row();actions.setPadding(0,dp(15),0,dp(12));actions.addView(play);Button favorite=button(tr("收藏到…","Save to…"),v->chooseFavorite(value.video));LinearLayout.LayoutParams favLp=new LinearLayout.LayoutParams(-2,-2);favLp.leftMargin=dp(12);actions.addView(favorite,favLp);box.addView(actions);
            if(value.parts.size()>1){for(VideoApi.Part part:value.parts){Button b=button("P"+part.page+"  "+part.title,v->openPlayer(value.video,part.cid,0));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(44));lp.bottomMargin=dp(5);parts.addView(b,lp);}box.addView(partScroll,new LinearLayout.LayoutParams(-1,dp(110)));}box.addView(button(tr("关闭","Close"),v->closeModal()));play.requestFocus();},e->{status.setText(errorText(e));box.addView(button(tr("重试","Retry"),v->detail(selected)));box.addView(button(tr("关闭","Close"),v->closeModal()));});}
    protected void openPlayer(VideoApi.Video video,long cid,long position){closeModal();Intent intent=new Intent();intent.setClassName(this,"com.ecojust.bilitv.PlaybackActivity");intent.putExtra("bvid",video.bvid);intent.putExtra("cid",cid);intent.putExtra("positionSeconds",position);intent.putExtra("title",video.title);startActivity(intent);}
    private void chooseFavorite(VideoApi.Video video){if(profile==null){closeModal();requireAccount(()->chooseFavorite(video));return;}LinearLayout box=dialogBody(tr("选择收藏夹","Choose a folder"));TextView status=text(tr("正在读取…","Loading…"),13,MUTED);box.addView(status);request(()->accounts.folders(profile.mid,video.aid),folders->{box.removeView(status);ScrollView s=new ScrollView(this);LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);s.addView(list);for(AccountApi.Folder folder:folders){Button item=button((folder.selected?"✓  ":"+  ")+folder.title,v->confirmFavorite(video,folder));list.addView(item,new LinearLayout.LayoutParams(-1,dp(44)));}if(folders.isEmpty())list.addView(text(tr("请先在账号中创建收藏夹。","Create a folder on your account first."),13,MUTED));box.addView(s,new LinearLayout.LayoutParams(-1,dp(150)));box.addView(button(tr("取消","Cancel"),v->closeModal()));},e->{status.setText(errorText(e));box.addView(button(tr("重试","Retry"),v->chooseFavorite(video)));box.addView(button(tr("关闭","Close"),v->closeModal()));});}
    private void confirmFavorite(VideoApi.Video video,AccountApi.Folder folder){LinearLayout box=dialogBody(folder.selected?tr("移出收藏夹？","Remove from folder?"):tr("加入收藏夹？","Add to folder?"));box.addView(text(folder.title,16,INK));Button confirm=button(tr("确认","Confirm"),v->{for(int i=0;i<box.getChildCount();i++)box.getChildAt(i).setEnabled(false);request(()->{accounts.favorite(video.aid,folder.id,!folder.selected);return Boolean.TRUE;},ok->{closeModal();Toast.makeText(this,tr("收藏已更新","Favorites updated"),Toast.LENGTH_SHORT).show();if("favorites".equals(page)&&selectedFolder!=null)fetchFavorites();},e->{closeModal();Toast.makeText(this,errorText(e),Toast.LENGTH_LONG).show();});});confirm.setTag("confirm-favorite");box.addView(confirm);box.addView(button(tr("取消","Cancel"),v->closeModal()));}
    private void accountAction(){if(profile==null){if(session.hasSession())requireAccount(this::accountAction);else login();return;}LinearLayout box=dialogBody(profile.name);box.addView(text(tr("非官方客户端 · 账号仅保存在本机","Unofficial client · Account stays on this device"),12,MUTED));box.addView(button(tr("退出登录","Sign out"),v->{closeModal();session.clear();profile=null;selectedFolder=null;records.clear();accountLabel();navigate("search");}));box.addView(button(tr("关闭","Close"),v->closeModal()));}
    private void login(){LinearLayout box=dialogBody(tr("扫码登录","Sign in"));qrOpen=true;TextView status=text(tr("正在生成二维码…","Creating QR code…"),14,MUTED);box.addView(status);request(accounts::startQr,ticket->{if(!qrOpen)return;try{ImageView image=new ImageView(this);image.setImageBitmap(qr(ticket.url));image.setContentDescription(tr("使用哔哩哔哩手机端扫描","Scan with the Bilibili mobile app"));LinearLayout.LayoutParams qrLp=new LinearLayout.LayoutParams(dp(170),dp(170));qrLp.gravity=Gravity.CENTER_HORIZONTAL;box.addView(image,1,qrLp);status.setText(tr("用哔哩哔哩手机端扫码并确认","Scan and confirm with the Bilibili mobile app"));box.addView(button(tr("取消","Cancel"),v->closeModal()));poll(ticket,status,box);}catch(Exception e){status.setText(tr("无法生成二维码，请重试。","Unable to create QR code. Try again."));box.addView(button(tr("重新生成","New QR code"),v->login()));}},e->{status.setText(errorText(e));box.addView(button(tr("重试","Retry"),v->login()));box.addView(button(tr("取消","Cancel"),v->closeModal()));});}
    private Bitmap qr(String value)throws Exception{Map<EncodeHintType,Object> hints=new EnumMap<>(EncodeHintType.class);hints.put(EncodeHintType.ERROR_CORRECTION,ErrorCorrectionLevel.M);hints.put(EncodeHintType.MARGIN,2);BitMatrix matrix=new MultiFormatWriter().encode(value,BarcodeFormat.QR_CODE,512,512,hints);int[] pixels=new int[512*512];for(int y=0;y<512;y++)for(int x=0;x<512;x++)pixels[y*512+x]=matrix.get(x,y)?Color.BLACK:Color.WHITE;return Bitmap.createBitmap(pixels,512,512,Bitmap.Config.ARGB_8888);}
    private void poll(AccountApi.QrTicket ticket,TextView status,LinearLayout box){if(!active||!qrOpen)return;qrPoll=()->{if(!active||!qrOpen)return;request(()->accounts.pollQr(ticket),state->{if(!qrOpen)return;switch(state.status){case SUCCESS:profile=state.profile;qrOpen=false;accountLabel();closeModal();navigate(page);break;case EXPIRED:status.setText(tr("二维码已过期","QR code expired"));box.addView(button(tr("重新生成","New QR code"),v->login()));break;case SCANNED:status.setText(tr("已扫码，请在手机上确认","Scanned. Confirm on your phone."));poll(ticket,status,box);break;default:poll(ticket,status,box);}},e->{status.setText(errorText(e));box.addView(button(tr("重试","Retry"),v->login()));});};main.postDelayed(qrPoll,2200);}
    @Override protected void onResume(){super.onResume();active=true;if(resumeRead){resumeRead=false;if(readRetry!=null)readRetry.run();}else if(profile==null&&session.hasSession())request(accounts::profile,p->{profile=p;accountLabel();},e->{profile=null;accountLabel();});}
    @Override protected void onPause(){active=false;resumeRead=loading&&!qrOpen&&modal==null;closeModal();super.onPause();}
    @Override protected void onDestroy(){destroyed=true;closeModal();main.removeCallbacksAndMessages(null);worker.shutdownNow();thumbnails.close();super.onDestroy();}
    @Override public void onBackPressed(){if(modal!=null){closeModal();return;}if("favorites".equals(page)&&selectedFolder!=null){selectedFolder=null;fetchFolders();return;}if(!"search".equals(page)){navigate("search");return;}if(!query.isEmpty()){query="";searchInput.setText("");cancelPending();showWelcome();searchInput.requestFocus();return;}super.onBackPressed();}
}
